mapper.select:
select lcrbl.batch_ln_id, lcrbl.batch_id, lcr.repayment_id, lcr.withdraw_id, lcr.contract_id, lcr.times, lcr.cf_item, lcr.cf_type, lcr.cf_direction, lcr.cf_status, lcr.planned_due_date, lcrbl.planned_due_amount, lcr.due_date, lcr.due_amount, lcr.write_off_flag, lcr.write_off_amount, lcr.interest_period_days, lcr.interest_accrual_balance, lcr.relate_contract_id, lcr.rent_due_date, lcr.rent_due_amount, lcr.relate_contract_category, lcr.group_id, lcr.group_number, lcr.exchange_rate, lcr.retain_amount, lcr.is_system_flag, lcr.planned_calc_date, lcr.received_bank_account_name, lcr.received_bp_name, lcr.cny_due_amount, lcr.confirm_flag, lcr.received_bank_account_num, (CASE WHEN (lcr.confirm_flag = 'Y') THEN '已确认' ELSE '未确认' END) confirm_flag_n, (SELECT hct.description FROM hls_cashflow_type hct WHERE hct.cf_type = lcr.cf_type AND hct.enabled_flag = 'Y') cf_type_desc, (SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = lcr.cf_type AND hci.cf_item = lcr.cf_item AND hci.enabled_flag = 'Y') cf_item_desc, (SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = lcr.cf_type AND hci.cf_item = lcr.cf_item AND hci.enabled_flag = 'Y') cf_item_n, ROUND((NVL(lcr.exchange_rate, 1) * lcr.planned_due_amount), 2) cny_planned_due_amount, (SELECT scv.meaning FROM sys_code_value_b_v scv WHERE scv.code_value = lcr.write_off_flag AND scv.code = 'LON.WRITE_OFF_FLAG') write_off_flag_desc, (lcr.due_amount - nvl(lcr.write_off_amount, 0)) AS remain_payback_amount, (select lcw.withdraw_number from lon_contract_withdraw lcw where lcw.withdraw_id = lcr.withdraw_id) as withdraw_number, lcr.currency, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'CHS.CURRENCY_TYPE' and scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scvb.value = lcr.currency) as currency_n, (select hbm.bp_name from lon_contract lc, hls_bp_master hbm where lc.contract_id = lcr.contract_id and lc.credit_bp_id = hbm.bp_id) as credit_bp_id_n, (select lc.finance_amount from lon_contract lc where lc.contract_id = lcr.contract_id) as finance_amount, (select scv.MEANING from sys_code_b sc, sys_code_value_b scv, lon_contract lc where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'FIN.CREDIT_METHOD' and scv.value = lc.document_type and lc.contract_id = lcr.contract_id) document_type_n, (select s.MEANING value_name from sys_code_value_b_v s, lon_contract_withdraw lcw where s.code = 'FIN.CONTRACT_LOAN_TYPE' and s.code_value = lcw.contract_loan_type and lcr.withdraw_id = lcw.withdraw_id) as contract_loan_type_n, (select lc.contract_number from lon_contract lc where lc.contract_id = lcr.contract_id) as contract_number, lcrbl.repayment_date, lcrbl.OUT_BANK_ACCOUNT_ID, lcrbl.OUT_BANK_ACCOUNT_NAME, lcrbl.OUT_BANK_ACCOUNT_NAME OUT_BANK_ACCOUNT_ID_N, lcrbl.OUT_BANK_ACCOUNT_NUM, cw.with_bank_account_id, cw.with_bank_account_name, cw.with_bank_account_num
from LON_CON_REPAYMENT_BATCH_LN lcrbl, lon_contract_repayment lcr, lon_contract_withdraw cw where lcr.repayment_id = lcrbl.repayment_id AND lcr.withdraw_id = cw.withdraw_id and lcrbl.batch_id = #{batchId}
and ((#{interestFlag} = 'Y' and lcr.cf_item in (301,302)) or (#{interestFlag} = 'N' and lcr.cf_item not in (301,302)))
